 full outer join camunda.act_hi_identitylink oplog on oplog.id_ = (select id_ from camunda.act_hi_identitylink where task_id_ = task.id_ and type_ = ''assignee'' and user_id_ = task.assignee_ order by timestamp_ desc limit 1)

right join camunda.act_id_membership memb on task.assignee_ = memb.user_id_
right join camunda.act_hi_identitylink idl on idl.task_id_ = task.id_ and idl.type_= ''candidate''
left join camunda.act_id_group grp on grp.id_ = idl.group_id_ and grp.id_ = memb.group_id_
where task.assignee_ is not null   group by
pdef.name_, task.assignee_, task.name_'::text WHERE
idashboardqueryid = 59;



UPDATE ui.dashboardquery SET
vcdashboardquery = '{"All": "select result->''score''->>''decisiondetails'' as \"decisiondetails\", ilivemessageid as \"ILiveMessageID\", vcmsgid as \"UniqueID\", vcclassname as \"Class\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \"Time\", dobservationamount as \"Amount\", score as \"Score\",  cast(result->''score''->>''bpass'' as text)as \"FRMPass\", vcpayeraccountexternalid as \"Payer Account\", vcpayeraddr as \"PayerVPA\", vcpayeeaccountexternalid as \"Payee Account\", vcpayeeaddr as \"PayeeVPA\", null as \"FailedRule\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \"PayerName\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \"PayeeName\" from transactions.trans where score >= :score and dttrxntime > cast(current_date as timestamp)  order by dttrxntime desc limit 50;",
"Other": "select result->''score''->>''decisiondetails'' as \"decisiondetails\", ilivemessageid as \"ILiveMessageID\", vcmsgid as \"UniqueID\", vcclassname as \"Class\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \"Time\", dobservationamount as \"Amount\", score as \"Score\",  cast(result->''score''->>''bpass'' as text)as \"FRMPass\", vcpayeraccountexternalid as \"Payer Account\", vcpayeraddr as \"PayerVPA\", vcpayeeaccountexternalid as \"Payee Account\", vcpayeeaddr as \"PayeeVPA\", null as \"FailedRule\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \"PayerName\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \"PayeeName\" from transactions.trans where score >= :score and dttrxntime > cast(current_date as timestamp)  and vcclassname  = :className order by dttrxntime desc limit 50;"}'::text WHERE
idashboardqueryid = 55;




